#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <bitset>

using namespace std;

/**
 * Problem: 10613 - Tug of War
 * 
 * 解題思路：
 * 1. 這是一個子集和問題的變體，限制子集的大小必須是 n/2 或 (n+1)/2。
 * 2. 令 n 為總人數，W 為總重量。
 * 3. 我們需要找到一個子集，人數為 m = n/2，其重量和 S 使得 |S - (W-S)| 最小。
 * 4. 使用動態規劃：dp[i] 是一個 bitset，第 j 位為 1 表示可以用 i 個人組成重量 j。
 * 5. dp[i] |= (dp[i-1] << weight)
 */

int main() {
    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;
        vector<int> weights(n);
        int total_weight = 0;
        for (int i = 0; i < n; ++i) {
            cin >> weights[i];
            total_weight += weights[i];
        }

        // dp[i] 存儲使用 i 個人可以達到的重量組合
        // 總重量最大 100 * 450 = 45000
        vector<bitset<45001>> dp(n / 2 + 2);
        dp[0][0] = 1;

        for (int w : weights) {
            for (int i = min(n / 2 + 1, (int)weights.size()); i >= 1; --i) {
                dp[i] |= (dp[i - 1] << w);
            }
        }

        int best_s = 0;
        int min_diff = total_weight;

        // 檢查 n/2 人和 (n+1)/2 人的情況
        int target_counts[] = {n / 2, (n + 1) / 2};
        for (int m : target_counts) {
            if (m > n / 2 + 1) continue;
            for (int s = 0; s <= total_weight; ++s) {
                if (dp[m][s]) {
                    int diff = abs(s - (total_weight - s));
                    if (diff < min_diff) {
                        min_diff = diff;
                        best_s = s;
                    }
                }
            }
        }

        int w1 = best_s, w2 = total_weight - best_s;
        if (w1 > w2) swap(w1, w2);
        cout << w1 << " " << w2 << endl;
        if (T > 0) cout << endl;
    }
    return 0;
}
